$ErrorActionPreference='Stop'
Write-Host 'STORM FA: LEVEL200 GRADE20; 7 ITEMI PASTA; MYTH HONOR GOLD PLATINUM RUNES; WINGS AKTIVAIS LIMITS3/100'
Write-Host 'AIZVER SPELI; TIKAI TESTA VM 192.168.56.101; LEGEND UN DIAMOND VEL NAV IEKLAUTI'
$code=[Text.Encoding]::ASCII.GetString([Convert]::FromBase64String(''))
$receipt=Join-Path $env:USERPROFILE ('Downloads\Storm-Grant-Receipt-'+(Get-Date -Format 'yyyyMMdd-HHmmss')+'.txt')
$lines=@($code | ssh root@192.168.56.101 python3 - --apply)
$exit=$LASTEXITCODE
$lines|Set-Content -LiteralPath $receipt -Encoding UTF8
$lines|ForEach-Object {Write-Host $_}
Write-Host ('REPORT='+$receipt)
if($exit -ne 0 -or !($lines|Select-String -SimpleMatch 'STORM_MAX_GEAR_CONFIRMED;','STORM_MAX_GEAR_ALREADY_GRANTED;')){throw 'STORM_GRANT_NOT_CONFIRMED; ATSUTI_IZVADI'}
